#include "csvp_schema.h"
#include <string.h>

uint32_t csvp_anchor_hash(const uint16_t *text,size_t len) {
    uint32_t h=2166136261u;
    for(size_t i=0;i<len;i++) {
        uint16_t c=text[i];
        h=(h^(uint8_t)c)*16777619u;
        h=(h^(uint8_t)(c>>8))*16777619u;
    }
    return h;
}

